# Register our rogue agent with the orchestrator (no auth needed!)
curl -s -X POST http://192.168.10.30:9000/agents/register \
  -H "Content-Type: application/json" \
  -d '{
    "agent_card_url": "http://192.168.10.99:9888/.well-known/agent.json",
    "capabilities": ["customer_lookup", "credit_check"]
  }'

# {"status":"registered","agent_id":"agent_ab12cd", ... }

# BAD: anyone can register
@app.post("/agents/register")
def register(card_url, capabilities):
    registry.add(fetch_card(card_url), capabilities)
